-- aria:manager-weight-approval's computed Difference field (weight_difference_display,
-- W2-W3) is TankerInbound-only — correct there (3-weighment model), but wrong
-- for M10.ReturnStockIn, which only has 2 weighments (no W3). Per direct
-- request ("Weighment officer: second weight and expected weight difference,
-- with reason, manager approval"), adding a parallel ReturnStockIn-only
-- computed field using W1 (the only earlier weighment available in a
-- 2-weighment flow) as the "expected" baseline against W2 (the post-unload
-- weighment that lands the instance on WEIGHMENT_2). Kept as separate field
-- names from the existing w2_weight_kg/w3_weight_kg/weight_difference_display
-- trio so M10.TankerInbound's behavior is untouched.
UPDATE page_version pv
  JOIN page_definition pd ON pd.current_version_id = pv.id
   SET pv.body_json = '{"kind": "layout", "schemaVersion": 2, "entity": "GatePass", "layout": [{"kind": "Grid", "columns": 12, "gap": 16, "children": [{"kind": "Section", "title": "Weight Verification — Manager Approval", "span": 12, "subtitle": "Final (third) weight captured at the exit. Pick the gate pass showing WEIGHMENT_3, confirm W3 against the second weight; if there is a difference, record the reason. APPROVE to send the vehicle to the gate, or REJECT it.", "children": [{"kind": "Form", "bindings": {"fields": [{"name": "gpNumber", "label": "Gate Pass # (scan / pick / type)", "type": "select", "required": true, "freeSolo": true, "scannable": true, "optionsSource": {"type": "datasource", "spec": {"type": "entity", "entity": "GatePass", "joins": [{"entity": "WorkflowInstance", "as": "wi", "on": "gate_pass.workflow_instance_id = wi.id"}, {"entity": "WeighmentCaptureDetail", "as": "wcd3", "on": "wcd3.workflow_instance_id = gate_pass.workflow_instance_id", "fields": ["wcd3.w1_weight_kg as w1WeightKgVal", "wcd3.w2_weight_kg as w2WeightKgVal"]}], "filter": {"and": [{"field": "wi.assigned_role", "op": "eq", "value": "Manager"}, {"field": "wi.status", "op": "eq", "value": "OPEN"}]}, "select": ["id", "gp_number", "flow_variant_code"], "sort": [{"field": "gp_number", "dir": "desc"}]}, "valueField": "gp_number", "labelField": "gp_number"}, "onChangeFill": {"vehicle_no": "vehicle_no", "instanceId": "workflow_instance_id", "w2_weight_kg": "w2_weight_kg", "w3_weight_kg": "w3_weight_kg", "variance_reason": "variance_reason", "flow_variant_code": "flow_variant_code", "w1_weight_kg_display": "w1WeightKgVal", "w2_weight_kg_display": "w2WeightKgVal"}}, {"name": "vehicle_no", "label": "Vehicle", "type": "text", "readOnly": true}, {"name": "flow_variant_code", "label": "Flow Variant", "type": "text", "readOnly": true}, {"name": "w2_weight_kg", "label": "Second Weight (kg)", "type": "text", "readOnly": true, "visibleWhen": "#form.flow_variant_code == \'M10.TankerInbound\'"}, {"name": "w3_weight_kg", "label": "Third Weight (kg)", "type": "text", "readOnly": true, "visibleWhen": "#form.flow_variant_code == \'M10.TankerInbound\'"}, {"name": "weight_difference_display", "label": "Difference (W2 − W3) kg", "type": "number", "readOnly": true, "visibleWhen": "#form.flow_variant_code == \'M10.TankerInbound\'", "computedFrom": "#form.w2_weight_kg - #form.w3_weight_kg"}, {"name": "w1_weight_kg_display", "label": "Expected Weight (kg) — from first weighment", "type": "number", "readOnly": true, "visibleWhen": "#form.flow_variant_code == \'M10.ReturnStockIn\'"}, {"name": "w2_weight_kg_display", "label": "Second Weight (kg)", "type": "number", "readOnly": true, "visibleWhen": "#form.flow_variant_code == \'M10.ReturnStockIn\'"}, {"name": "rsi_weight_difference_display", "label": "Difference (Expected − Second) kg", "type": "number", "readOnly": true, "visibleWhen": "#form.flow_variant_code == \'M10.ReturnStockIn\'", "computedFrom": "#form.w1_weight_kg_display - #form.w2_weight_kg_display"}, {"name": "variance_reason", "label": "Weight-difference reason (if any)", "type": "textarea"}]}}, {"kind": "Stack", "direction": "row", "gap": 12, "children": [{"kind": "WorkflowActionButton", "label": "✓ Approve — Ready for Exit", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "targetState": "READY_FOR_EXIT", "color": "primary", "submitValues": {"status": "APPROVED"}}, {"kind": "WorkflowActionButton", "label": "✗ Reject", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "targetState": "REJECTED_BY_MANAGER", "color": "error", "submitValues": {"status": "REJECTED"}}]}]}]}]}'
 WHERE pd.code = 'aria:manager-weight-approval' AND pv.status = 'PUBLISHED';
